+
+  it("supports the spend reserve and refund", async () => {
+    const kv = createMemoryKV();
+    expect(await kv.incrBy("spend", IMAGE_COST_MICRO)).toBe(IMAGE_COST_MICRO);
+    expect(budgetExceeded(IMAGE_COST_MICRO, 10_000_000)).toBe(false);
